changeSet.sql:
create or alter procedure api.UpsertGroups @executionId int, @lookupFieldsPassedByValue bit = 0 as begin set nocount on; declare @isInsert bit, @userId int, @date datetime, @object varchar(50) = 'Group', @assetTypeId int, @transactionCompleted bit = 0;
declare @errormessage nvarchar(4000)='';
select @assetTypeId = ID from AssetType where Object = 'GroupType';
select @isInsert = iif([Action] = 19, 1, 0), @userId = ResourceID, @date = StartedOn from api.Execution where ID = @executionId;
drop table if exists #Items; create table #Items ( ItemNumber int, [Uid] uniqueidentifier, IsValid bit, IsSuccess bit, ObjectID int, AssetID bigint, Name nvarchar(250), Description nvarchar(max), PrimaryOwnerUid uniqueidentifier, PrimaryOwnerResourceID int, SecondaryOwnerUid uniqueidentifier, SecondaryOwnerResourceID int, IsActiveDirectoryGroup bit, [Message] nvarchar(max) );
drop table if exists #Fields; create table #Fields (ItemNumber int, FieldName nvarchar(250), FieldTypeID int, FieldValue nvarchar(max), LookupValue nvarchar(max));
-- Get data from JSON columns in api.ExecutionItem insert into #Items (ItemNumber, Uid, Name, Description, PrimaryOwnerUid, SecondaryOwnerUid, IsActiveDirectoryGroup) select ItemNumber, JSON_VALUE(Properties, '$.Uid'), JSON_VALUE(Properties, '$.Name'), JSON_VALUE(Properties, '$.Description'), JSON_VALUE(Properties, '$.PrimaryOwnerUid'), JSON_VALUE(Properties, '$.SecondaryOwnerUid'), cast(coalesce(JSON_VALUE(Properties, '$.IsActiveDirectoryGroup'), 'false') as bit) from api.ExecutionItem where ExecutionId = @executionId;
insert into #Fields (ItemNumber, FieldName, FieldTypeID, FieldValue, LookupValue) select i.ItemNumber, f.FieldName, f.FieldTypeID, f.FieldValue, f.LookupValue from api.ExecutionItem i cross apply openjson(i.CustomProperties) with (FieldName nvarchar(250), FieldTypeID int, FieldValue nvarchar(max), LookupValue nvarchar(max)) f where ExecutionId = @executionId;
-- Validate incoming data. if @isInsert = 1 begin update t set t.ObjectID = s.ID, t.IsValid = 0, t.Message = 'Already a group called [' + s.name + '];' from #Items t inner join [Group] s on s.Name = t.Name and t.Name is not null;
update t set t.ObjectID = s.ID, t.IsValid = 0, t.Message = coalesce(t.Message,'') + ' Group already exists.' from #Items t inner join [Group] s on s.Uid = t.Uid and t.Uid is not null;
-- Populate any missing uids for inserts if not already present. update #Items set Uid = newid() where Uid is null and IsValid is null and ObjectID is null; end else begin update t set t.IsValid = 0, t.Message = 'Group does not exist.' from #Items t left join [Group] s on s.Uid = t.Uid and t.Uid is not null where s.ID is null;
-- Populate internal ID for group based on the incoming Uid. update t set t.ObjectID = s.ID from #Items t inner join [Group] s on s.Uid = t.Uid and t.Uid is not null and IsValid is null; end
update T set T.PrimaryOwnerResourceID = coalesce(S.ResourceID,T.PrimaryOwnerResourceID), T.IsValid = iif(S.ResourceID is null, 0, T.IsValid), T.Message = iif(S.ResourceID is null, 'Primary Owner Uid provided is not a resource uid.', T.Message) from #Items T left join reporting.Global_Resource S on S.Uid = T.PrimaryOwnerUid where T.PrimaryOwnerUid is not null and T.IsValid is null;
update T set T.SecondaryOwnerResourceID = coalesce(S.ResourceID,T.SecondaryOwnerResourceID), T.IsValid = iif(S.ResourceID is null, 0, T.IsValid), T.Message = iif(S.ResourceID is null, 'Secondary Owner Uid provided is not a resource uid.', T.Message) from #Items T left join reporting.Global_Resource S on S.Uid = T.SecondaryOwnerUid where T.SecondaryOwnerUid is not null and T.IsValid is null;
drop table if exists #dup;
select t.name into #dup from #Items t where t.Name is not null group by t.name having count(1) > 1;
update t set t.IsValid = 0, t.Message = 'Duplicate Names: ' + t.name + '. Name must be unique within a batch.;' from #Items t inner join #dup s on s.Name = t.Name;
drop table if exists #dup;
delete f from #Fields f inner join #Items T on f.ItemNumber = t.ItemNumber and t.IsValid = 0;
exec api.ValidateLookupFields @lookupFieldsPassedByValue;
update T set T.IsValid = 0, T.Message = 'Invalid lookup value for field ' + F.FieldName + '. ' from #Items T inner join #Fields f on f.ItemNumber = t.ItemNumber inner join FieldType s on s.ID = f.FieldTypeID and s.[Type] = 'Lookup' where coalesce(f.FieldValue,'') !='' and f.LookupValue is null and T.IsValid is null;
delete f from #Fields f inner join #Items T on f.ItemNumber = t.ItemNumber and t.IsValid = 0;
begin try begin transaction;
if @isInsert = 1 begin -- Create groups that do not yet exist in environment, and were successfully validated. insert into [Group] (Uid, Name, Description, IsActiveDirectoryGroup, PrimaryOwnerResourceID, SecondaryOwnerResourceID, UpdatedBy, UpdatedOn) select Uid, Name, Description, IsActiveDirectoryGroup, PrimaryOwnerResourceID, SecondaryOwnerResourceID, @userId, @date from #Items where IsValid is null;
-- Get the new internal IDs for newly created groups. update t set t.ObjectID = s.ID from #Items t inner join [Group] s on s.Uid = t.Uid and IsValid is null; end else begin update t set T.Name = S.Name, T.Description = S.Description, T.IsActiveDirectoryGroup = S.IsActiveDirectoryGroup, T.PrimaryOwnerResourceID = S.PrimaryOwnerResourceID, T.SecondaryOwnerResourceID = S.SecondaryOwnerResourceID, T.UpdatedBy = @userId, T.UpdatedOn = @date from [Group] t inner join #Items s on s.ObjectID = t.ID and IsValid is null; end
-- Asset merge dbo.Asset as T using (select * from #Items where IsValid is null) as S on (T.Object = 'Group' and T.ObjectID = S.ObjectID) when matched then update set T.UpdatedOn = @date, T.UpdatedBy = @userId when not matched by target then insert ([uid], [AssetTypeID], [State], [Object], [ObjectID], [CreatedOn], [CreatedBy], [UpdatedOn], [UpdatedBy]) values (S.Uid, @assetTypeId, 1, 'Group', S.ObjectID, @date, @userId, @date, @userId);
update T set T.AssetID = A.ID from #Items T inner join dbo.Asset A on A.Object = 'Group' and A.ObjectID = T.ObjectID;
-- Asset Path merge dbo.AssetPath as T using ( select i.AssetID as ID, ( select 1 as '@level', 1 as '@position', @assetTypeId as '@assetTypeId', i.AssetID as '@assetId', g.Name as 'data()' for xml path('segment'), root('path') ) as Segments from #Items i inner join [Group] g on g.ID = i.ObjectID ) as S on (T.ID = S.ID) when matched then update set T.Segments = S.Segments when not matched by target then insert (ID, Segments) values (S.ID, S.Segments);
-- Asset Display Value merge dbo.AssetDisplayValue as T using ( select i.AssetID as ID, g.Name as DisplayValue from #Items i inner join [Group] g on g.ID = i.ObjectID ) as S on (T.AssetID = S.ID) when matched then update set T.DisplayValue = S.DisplayValue, T.DisplayValuePrefix = substring(S.DisplayValue, 1, 250) when not matched by target then insert (AssetID, DisplayValue, DisplayValuePrefix) values (S.ID, S.DisplayValue, substring(S.DisplayValue, 1, 250));
-- Ensure that primary and secondary owners are members of the group. insert into ResourceGroup (ResourceID, GroupID) select PrimaryOwnerResourceID, ObjectID from #Items i left join ResourceGroup rg on rg.GroupID = i.ObjectID and rg.ResourceID = i.PrimaryOwnerResourceID where IsValid is null and rg.GroupID is null and i.PrimaryOwnerResourceID is not null;
insert into ResourceGroup (ResourceID, GroupID) select SecondaryOwnerResourceID, ObjectID from #Items i left join ResourceGroup rg on rg.GroupID = i.ObjectID and rg.ResourceID = i.SecondaryOwnerResourceID where IsValid is null and rg.GroupID is null and i.SecondaryOwnerResourceID is not null;
-- Resolve lookup field values and process data. exec api.UpsertItemFields @userId, @date, @object, @lookupFieldsPassedByValue;
exec api.UpsertChangeLog @executionId, @object;
commit transaction; set @transactionCompleted = 1; end try begin catch rollback transaction; set @errormessage = substring(ERROR_MESSAGE(),1,4000); end catch
if @transactionCompleted = 1 begin -- Updated the messaging. update #Items set Message = iif(@isInsert = 1, 'Successfully created group.', 'Successfully updated group.'), IsValid = 1 where IsValid is null
-- Update api.ExecutionItem update t set t.Success = s.IsValid, t.Message = s.Message from api.ExecutionItem t inner join #Items s on s.ItemNumber = t.ItemNumber and t.ExecutionId = @executionId;
update t set t.Properties = JSON_MODIFY(t.Properties, '$.assetId', s.AssetID) from api.ExecutionItem t inner join #Items s on s.ItemNumber = t.ItemNumber and t.ExecutionId = @executionId and s.AssetID is not null;
update t set t.Properties = JSON_MODIFY(t.Properties, '$.id', s.ObjectID) from api.ExecutionItem t inner join #Items s on s.ItemNumber = t.ItemNumber and t.ExecutionId = @executionId and s.ObjectID is not null;
update t set t.Properties = JSON_MODIFY(t.Properties, '$.Uid', cast(s.Uid as nvarchar(50))) from api.ExecutionItem t inner join #Items s on s.ItemNumber = t.ItemNumber and t.ExecutionId = @executionId and s.Uid is not null;
exec api.CompleteExecution @executionId, @date, ''; end else begin if (@errormessage is not null) begin exec api.CompleteExecution @executionId, @date, @errormessage; end else begin exec api.CompleteExecution @executionId, @date, 'Transaction failed to complete.'; end end end
